const newProblems=[
[1,0,'Кто где стоит?','Лена стоит в очереди третьей от начала и четвёртой от конца. Сколько всего детей в очереди?',6,['Сначала посчитай детей перед Леной и после неё.','Лену нужно посчитать только один раз.'],['Перед Леной 2 ребёнка: она третья.','После неё 3 ребёнка: она четвёртая с конца.','Всего 2 + 1 + 3 = 6 детей.']],
[1,1,'Поровну в коробках','В первой коробке 9 фишек, во второй — 3. Сколько фишек нужно переложить из первой во вторую, чтобы стало поровну?',3,['При перекладывании одна коробка уменьшается, а другая увеличивается.','Всего 12 фишек. Сколько должно быть в каждой?'],['Всего 9 + 3 = 12 фишек.','Поровну — это по 6 в каждой коробке.','Из первой нужно убрать 9 − 6 = 3 фишки. Проверяем: 3 + 3 = 6 во второй.']],
[1,2,'Квадраты из палочек','Для одного квадрата нужно 4 палочки. Два квадрата в ряд с общей стороной требуют 7 палочек. Сколько палочек нужно для трёх таких квадратов в ряд?',10,['Общая сторона принадлежит сразу двум квадратам.','Каждый следующий квадрат добавляет только 3 палочки.'],['На первый квадрат тратим 4 палочки.','На второй добавляем 3, на третий ещё 3.','Итого 4 + 3 + 3 = 10 палочек.']],
[2,0,'Кролики и куры','На ферме 8 животных — только кролики и куры. Всего у них 22 лапы. Сколько кроликов на ферме?',3,['Представь, что все 8 животных — куры.','Каждый кролик добавляет 2 лапы по сравнению с курицей.'],['Если бы все были курами, было бы 8 × 2 = 16 лап.','Разница: 22 − 16 = 6 лап.','Один кролик даёт 2 дополнительные лапы. Кроликов 6 : 2 = 3.']],
[2,1,'Звонки часов','Часы отбивают 3 удара за 4 секунды. Сколько секунд пройдёт от первого до последнего удара, когда часы пробьют 6 раз? Паузы между ударами одинаковы, длительностью удара пренебреги.',10,['Считай промежутки между ударами, а не сами удары.','У трёх ударов два промежутка, у шести — пять.'],['Между тремя ударами 2 промежутка. Один длится 4 : 2 = 2 секунды.','Между шестью ударами 5 промежутков.','Общее время 5 × 2 = 10 секунд.']],
[2,2,'Забор с проходом','У прямоугольного сада стороны 8 м и 5 м. В заборе оставят проход шириной 2 м. Сколько метров забора потребуется?',24,['Сначала найди длину всей границы.','На месте прохода забора не будет.'],['Периметр сада 2 × (8 + 5) = 26 м.','Из полной границы исключаем проход шириной 2 м.','Нужно 26 − 2 = 24 м забора.']],
[3,0,'Покупка тетрадей','За 4 одинаковые тетради и ручку за 18 рублей заплатили 50 рублей. Сколько стоит одна тетрадь?',8,['Сначала отдели стоимость ручки от всей покупки.','Оставшаяся сумма — за четыре одинаковые тетради.'],['Тетради вместе стоят 50 − 18 = 32 рубля.','Одна тетрадь стоит 32 : 4 = 8 рублей.','Проверяем: 4 × 8 + 18 = 50.']],
[3,1,'Библиотека','На полке 36 книг. Треть из них — сказки. Половина оставшихся — рассказы, остальные — стихи. Сколько книг со стихами?',12,['Вторая половина берётся от остатка, а не от 36.','Сначала найди, сколько книг осталось после сказок.'],['Сказок 36 : 3 = 12. Осталось 36 − 12 = 24 книги.','Рассказов половина остатка: 24 : 2 = 12.','Стихов 24 − 12 = 12 книг.']],
[3,2,'Рамка из клеток','На клетчатом листе выделили квадрат 5 × 5 клеток. Сколько клеток находится на его границе, если рамка имеет толщину в одну клетку?',16,['Удобнее вычесть внутренний квадрат из большого.','Внутри остаётся квадрат 3 × 3.'],['Во всём квадрате 5 × 5 = 25 клеток.','Внутренняя часть без рамки: 3 × 3 = 9 клеток.','Рамка содержит 25 − 9 = 16 клеток. Угловые клетки посчитаны один раз.']],
[4,0,'Секретное трёхзначное','В трёхзначном числе цифра сотен равна 4. Если поменять местами цифры десятков и единиц, число уменьшится на 27. Сумма этих двух цифр равна 9. Найди исходное число.',463,['Разность чисел зависит только от последних двух цифр.','Разность цифр десятков и единиц равна 27 : 9 = 3.'],['Пусть цифры десятков и единиц — a и b. Разность исходного и нового числа равна 9(a − b) = 27.','Значит a − b = 3. Вместе с a + b = 9 это даёт a = 6, b = 3.','Сотни равны 4, поэтому исходное число 463. Проверка: 463 − 436 = 27.']],
[4,1,'Встреча с остановкой','Два велосипедиста выехали навстречу из пунктов на расстоянии 60 км со скоростями 12 и 18 км/ч. Через час первый остановился на час, а второй продолжал ехать. Через сколько часов после старта они встретились?',12/5,['За первый час они вместе проехали 30 км.','Во время остановки расстояние уменьшилось ещё на 18 км.'],['После первого часа между ними 60 − 12 − 18 = 30 км.','За час остановки второй проехал 18 км. Осталось 12 км.','После возобновления движения скорость сближения 30 км/ч. Нужно ещё 12/30 = 2/5 часа.','Всего 1 + 1 + 2/5 = 12/5 часа.']],
[4,2,'Восстанови запас','В первый день продали 1/3 всех билетов, во второй — половину остатка. После этого осталось 20 билетов. Сколько билетов было сначала?',60,['Проследи, какая доля исходного количества осталась.','После первого дня осталось 2/3, после второго — половина этой доли.'],['После первого дня осталось 2/3 всех билетов.','Половина от 2/3 — это 1/3 исходного количества.','Если 1/3 равна 20, то всего было 20 × 3 = 60 билетов.']],
[5,0,'Одновременный старт','Два маяка вспыхивают каждые 18 и 24 секунды. Они вспыхнули одновременно. Через сколько секунд это повторится впервые?',72,['Искомое время делится и на 18, и на 24.','Нужно наименьшее общее кратное.'],['18 = 2 × 3², 24 = 2³ × 3.','НОК = 2³ × 3² = 72.','Через 72 секунды первый маяк завершит 4 цикла, второй — 3.']],
[5,1,'Две трубы','Первая труба наполняет пустой бассейн за 6 часов, вторая — за 3 часа. За сколько часов они наполнят его вместе при постоянном расходе?',2,['Складывать нужно доли бассейна за час, а не время.','Производительности равны 1/6 и 1/3 бассейна в час.'],['За час первая труба заполняет 1/6 бассейна, вторая 1/3.','Вместе за час: 1/6 + 1/3 = 1/2 бассейна.','На целый бассейн нужно 1 : (1/2) = 2 часа.']],
[5,2,'Куб без краски','Куб с ребром 4 см покрасили снаружи, а затем разрезали на кубики с ребром 1 см. Сколько маленьких кубиков не имеют ни одной окрашенной грани?',8,['Без краски остались только внутренние кубики.','Убери внешний слой с каждой стороны.'],['Наружные кубики касаются хотя бы одной грани большого куба и окрашены.','Внутри по каждому направлению остаётся 4 − 2 = 2 кубика.','Неокрашенных кубиков 2 × 2 × 2 = 8.']],
[6,0,'Два раствора','Смешали 200 г раствора с 10% соли и 300 г раствора с 20% соли. Какова массовая доля соли в смеси в процентах?',16,['Отдельно посчитай массу соли в каждом растворе.','Процент смеси считай от общей массы 500 г.'],['В первом растворе соли 200 × 0,10 = 20 г, во втором 300 × 0,20 = 60 г.','Всего соли 80 г, масса смеси 500 г.','Массовая доля 80/500 × 100% = 16%.']],
[6,1,'Целые точки','Сколько целых чисел x удовлетворяют неравенству |x − 2| < 4?',7,['Модуль показывает расстояние от x до числа 2.','Нужно строго меньше 4, поэтому граничные точки не входят.'],['Расстояние до 2 меньше 4: −4 < x − 2 < 4.','Прибавляем 2: −2 < x < 6.','Целые числа: −1, 0, 1, 2, 3, 4, 5 — всего 7.']],
[6,2,'Кратчайшие маршруты','На сетке нужно попасть из нижнего левого угла в верхний правый, сделав ровно 3 шага вправо и 2 шага вверх. Сколько разных кратчайших маршрутов?',10,['Любой маршрут состоит из пяти шагов.','Достаточно выбрать две позиции для шагов вверх.'],['Обозначим шаги В (вправо) и У (вверх). В маршруте 5 позиций.','Выбираем две позиции для У: 5 × 4 способов с учётом порядка выбора.','Порядок выбора двух позиций не важен, поэтому делим на 2: 5 × 4 / 2 = 10.']],
[7,0,'Путь по реке','Катер прошёл 36 км по течению за то же время, за какое прошёл 24 км против течения. Скорость течения 3 км/ч. Найди собственную скорость катера в км/ч.',15,['Обозначь собственную скорость v, она больше 3.','Равенство времён: 36/(v + 3) = 24/(v − 3).'],['Скорости по течению и против течения: v + 3 и v − 3.','Из равенства времён: 36(v − 3) = 24(v + 3).','36v − 108 = 24v + 72, значит 12v = 180 и v = 15.','Проверка: 36/18 = 2 часа, 24/12 = 2 часа.']],
[7,1,'Сумма и произведение','Известно, что a + b = 10 и ab = 21. Найди a³ + b³, не находя сами числа a и b.',370,['Раскрой куб суммы и сравни с нужным выражением.','a³ + b³ = (a + b)³ − 3ab(a + b).'],['(a + b)³ = a³ + 3a²b + 3ab² + b³.','Средние слагаемые равны 3ab(a + b).','Поэтому a³ + b³ = 10³ − 3 × 21 × 10 = 1000 − 630 = 370.']],
[7,2,'Биссектриса и равенство','В треугольнике ABC угол A равен 40°, угол B — 80°. Биссектриса угла C пересекает AB в точке D. Найди угол ADC в градусах.',110,['Сначала найди угол C, затем половину этого угла.','Рассмотри треугольник ACD.'],['Угол C = 180° − 40° − 80° = 60°.','CD делит угол C пополам, поэтому угол ACD = 30°.','В треугольнике ACD угол ADC = 180° − 40° − 30° = 110°.']],
[8,0,'Квадраты корней','Вычисли (√7 + √3)² + (√7 − √3)².',20,['Раскрой оба квадрата суммы и разности.','Слагаемые с произведением корней взаимно уничтожатся.'],['Первый квадрат: 7 + 2√21 + 3 = 10 + 2√21.','Второй квадрат: 7 − 2√21 + 3 = 10 − 2√21.','Складываем: 10 + 10 = 20.']],
[8,1,'Корни с условием','Один корень уравнения x² − px + 12 = 0 втрое больше другого. Найди положительное значение p.',8,['Пусть корни t и 3t. Используй произведение по Виету.','3t² = 12, а p равно сумме корней.'],['По Виету t × 3t = 12, значит t² = 4 и t = ±2.','Сумма корней p = t + 3t = 4t.','Возможны p = 8 и p = −8. Положительное значение — 8.']],
[8,2,'Точка внутри','Точка M лежит внутри прямоугольника ABCD. Известно, что MA² = 10, MB² = 25, MC² = 40. Найди MD². Вершины перечислены по порядку.',25,['Опусти перпендикуляры к сторонам и вырази расстояния по Пифагору.','Суммы квадратов расстояний до противоположных вершин одинаковы.'],['Пусть A=(0,0), B=(a,0), C=(a,b), D=(0,b), M=(x,y).','MA² + MC² = x² + y² + (a − x)² + (b − y)².','MB² + MD² дают те же четыре слагаемых.','Значит MD² = MA² + MC² − MB² = 10 + 40 − 25 = 25.']],
[9,0,'Касание оси','При каком значении k парабола y = x² − 4x + k касается оси x?',4,['Касание означает ровно одну общую точку с осью.','Вершина параболы должна лежать на оси x.'],['Выделим квадрат: y = (x − 2)² + k − 4.','Вершина имеет координаты (2; k − 4).','Для касания оси x нужно k − 4 = 0, значит k = 4.']],
[9,1,'Места в зале','В первом ряду зала 12 мест, а в каждом следующем на 2 места больше. Всего 15 рядов. Сколько мест в зале?',390,['Количество мест образует арифметическую прогрессию.','Найди последний ряд и используй формулу суммы.'],['В пятнадцатом ряду 12 + 14 × 2 = 40 мест.','Сумма S₁₅ = 15(12 + 40)/2.','Получаем 15 × 26 = 390 мест.']],
[9,2,'Без возвращения','В мешке 4 красных и 3 синих шара. Наугад последовательно достают два шара без возвращения. Какова вероятность, что они одного цвета?',3/7,['Разбей событие на два случая: оба красные или оба синие.','После первого шара общее число шаров уменьшается на 1.'],['Вероятность двух красных: (4/7) × (3/6) = 2/7.','Вероятность двух синих: (3/7) × (2/6) = 1/7.','Эти случаи несовместны, поэтому складываем: 2/7 + 1/7 = 3/7.']],
[10,0,'Без поиска угла','Для некоторого угла α известно sin α + cos α = 1/2. Найди sin 2α.',-0.75,['Возведи данное равенство в квадрат.','Используй sin² α + cos² α = 1.'],['(sin α + cos α)² = 1 + 2 sin α cos α = 1/4.','Следовательно 2 sin α cos α = 1/4 − 1 = −3/4.','По формуле двойного угла sin 2α = −3/4.']],
[10,1,'Сначала область определения','Реши уравнение log₂(x − 1) + log₂(x + 1) = 3. Введи действительный корень.',3,['Оба аргумента должны быть положительны, значит x > 1.','Сложение логарифмов заменяется логарифмом произведения.'],['Область определения: x − 1 > 0 и x + 1 > 0, то есть x > 1.','log₂((x − 1)(x + 1)) = 3, значит x² − 1 = 8.','Из x² = 9 получаем x = ±3.','Условию x > 1 удовлетворяет только x = 3.']],
[10,2,'Пирамида внутри куба','В кубе с ребром 6 см основание пирамиды — одна грань куба, вершина — центр противоположной грани. Найди объём пирамиды в см³.',72,['Высота пирамиды — расстояние между противоположными гранями.','Объём пирамиды равен трети произведения площади основания на высоту.'],['Площадь квадратного основания S = 6² = 36 см².','Перпендикулярная высота h = 6 см.','V = Sh/3 = 36 × 6 / 3 = 72 см³.']],
[11,0,'Наибольшее на отрезке','Найди наибольшее значение функции f(x) = x³ − 3x на отрезке [−2; 2].',2,['Проверь критические точки и оба конца отрезка.','Производная 3x² − 3 обращается в ноль при x = ±1.'],['f′(x) = 3x² − 3. Критические точки −1 и 1 лежат на отрезке.','Вычисляем: f(−2) = −2, f(−1) = 2, f(1) = −2, f(2) = 2.','Наибольшее из этих значений — 2. Оно достигается при x = −1 и x = 2.']],
[11,1,'Площадь по обе стороны оси','Найди площадь фигуры между графиком y = x² − 1 и осью x на отрезке [−1; 2].',8/3,['Функция меняет знак в точке x = 1.','На [−1; 1] интегрируй 1 − x², на [1; 2] — x² − 1.'],['На [−1; 1] график ниже оси: площадь равна интегралу 1 − x², то есть [x − x³/3] от −1 до 1 = 4/3.','На [1; 2] график выше оси: площадь равна [x³/3 − x] от 1 до 2 = 4/3.','Общая площадь 4/3 + 4/3 = 8/3.']],
[11,2,'Ровно два успеха','Вероятность попадания при одном выстреле равна 0,8. Сделали 3 независимых выстрела. Какова вероятность ровно двух попаданий?',0.384,['Сначала найди вероятность одного конкретного порядка двух попаданий и промаха.','Промах может стоять на любой из трёх позиций.'],['Для порядка попадание–попадание–промах вероятность равна 0,8² × 0,2 = 0,128.','Промах может быть первым, вторым или третьим: 3 несовместных варианта.','Итоговая вероятность 3 × 0,128 = 0,384.']]
];

for(const [grade,topic,title,question,answer,hints,steps] of newProblems){tasks.push({id:`${grade}-${topic}-challenge`,grade,topic,topicName:curriculum[grade][topic][0],level:new Set(['1-0','2-2','3-0','3-1','4-2','5-0','9-1','10-2','11-2']).has(`${grade}-${topic}`)?1:2,title,question,answer,hint:hints[0],hints,steps,solution:steps.join(' '),isNew:true})}
// Replace two low-information exercises while retaining old records under their original IDs.
const improved=[
['6-1-2','Сумма целых','Найди сумму всех целых чисел x, для которых |x − 3| ≤ 5.',33,['Неравенство описывает числа на расстоянии не больше 5 от числа 3.','Границы включены: от −2 до 8.'],['−5 ≤ x − 3 ≤ 5, поэтому −2 ≤ x ≤ 8.','Всего 11 целых чисел, симметричных относительно 3.','Их сумма равна 11 × 3 = 33.']],
['2-1-1','Время до кружка','Сейчас 14:35. Кружок начнётся в 15:20. Сколько минут осталось?',45,['Сначала посчитай время до 15:00.','Затем добавь минуты после 15:00.'],['От 14:35 до 15:00 осталось 25 минут.','От 15:00 до 15:20 ещё 20 минут.','Всего 25 + 20 = 45 минут.']]
];
for(const [id,title,question,answer,hints,steps] of improved){const t=tasks.find(t=>t.id===id);Object.assign(t,{id:id+'-v2',title,question,answer,hints,hint:hints[0],steps,solution:steps.join(' ')})}
for(const t of tasks){t.steps??=t.solution.split(/;\s*/).filter(Boolean);t.hints??=[t.hint];t.goal=['Применить основное правило','Связать несколько действий','Найти идею и объяснить ход мысли'][t.level]}
